function ShiSanZhangRoomScene:getToDisbandFuncs()
    local data = {}
    data.quitRoomHandler = handler(self, self.quitRoom)
    data.disbandRoomHandler = handler(self, self.disbandRoom)
    data.rejectDisbandRoomHandler = handler(self, self.rejectDisband)
    data.agreeDisbandRoomHandler = handler(self, self.agreeDisband)
    data.showMoreFuncHandler = handler(self, self.loadMoreFuncLayer)
    --data.showGameMsgLayerHandler = handler(self, self.loadGameMsgLayer)
    data.voiceRecordHandler = handler(self,self.addVoiceRecordEvent)
    return data
end

function ShiSanZhangRoomScene:loadMoreFuncLayer()
    print("=====loadMoreFuncLayer=====")
    if tolua.isnull(ShiSanZhangRoomScene.moreFuncLayer) then
        ShiSanZhangRoomScene.moreFuncLayer = require("hall.roomCommonUI.GameMoreFuncLayer").new()
        self:addChild(ShiSanZhangRoomScene.moreFuncLayer, 99)
    else
        ShiSanZhangRoomScene.moreFuncLayer:setVisible(true)
        ShiSanZhangRoomScene.moreFuncLayer:showAni()
    end
end

function ShiSanZhangRoomScene:loadGameMsgLayer()
    if tolua.isnull(ShiSanZhangRoomScene.gameMsgLayer) then
        ShiSanZhangRoomScene.gameMsgLayer = require("hall.roomCommonUI.GameMsgLayer").new(self:getToSendFaceAndTxtFuncs())
        self:addChild(ShiSanZhangRoomScene.gameMsgLayer, 99)
        ShiSanZhangRoomScene.gameMsgLayer:setVisible(false)
    else
        ShiSanZhangRoomScene.gameMsgLayer:setVisible(true)
        ShiSanZhangRoomScene.gameMsgLayer:showContentByType(1)
    end
end

function ShiSanZhangRoomScene:getToSendFaceAndTxtFuncs()
    local data = {}
    data.sendFaceHand = handler(self, self.sendFaceByIdx)
    return data
end
