    SHISANZHANG_GAME_SCENE:stopAllActions()
    MA_CARD = nil
    CLUB_ID = nil
    g_guiNumber = nil
    -- FileMgr:debugGeloadPath(TpackageName)
end

return ShiSanZhangRoomScene